head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedRowOverColor]<br/>마우스 포인터가 포커스된 Body Row 에 오버될때 Row 의 배경색으로 적용될 색상을 설정합니다. rowMouseOver=true 이고 focusMode='row','both' 인 경우에 동작합니다.",
    "validation" : [
        "RowNum Column 에 selectedRowOverColor 를 적용하려면 rowNumRowMouseOverColor=true 이거나 rowNumBackgroundColor 가 미설정이어야 하며, RowStatus Column 의 배경색에는 항상 selectedRowOverColor 가 적용됩니다. (엔진 실측: 포커스 Row 마우스 오버 시 RowNum 은 rowNumRowMouseOverColor / rowNumBackgroundColor 설정과 무관하게 selectedRowOverColor 적용)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - rowMouseOver 는 본 샘플 검증 전제이므로 "true" 하드코딩
    //  - focusMode 는 selectedRowOverColor 가 동작하는 "both" 하드코딩
    //  - rowNumVisible / rowStatusVisible 는 RowNum / RowStatus Column 가시화를 위해 true 하드코딩
    //  - selectedRowColor 는 포커스 Row 가시화를 위해 기본색 부여
    //  - selectedRowOverColor 는 'red' 하드코딩 (RowNum/RowStatus 적용 색)
    //  - rowNumRowMouseOverColor (true/false), rowNumBackgroundColor (미설정/설정) 를 con 으로 노출하여
    //    RowNum Column 의 selectedRowOverColor 적용 조건을 가시화
    let properties = {
        dataList               : "data:dlt_bind",
        focusMode              : "both",
        rowMouseOver           : "true",
        rowNumVisible          : "true",
        rowStatusVisible       : "true",
        rowStatusHeaderValue   : "St.",
        selectedRowColor       : "lightgreen",
        selectedRowOverColor   : "red",
        rowNumRowMouseOverColor: con_rowNumRowMouseOverColor.getText(),
        rowNumBackgroundColor  : con_rowNumBackgroundColor.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbodymouseover"]);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblNumOver = (properties.rowNumRowMouseOverColor === '') ? '미설정' : properties.rowNumRowMouseOverColor;
    let lblNumBg = (properties.rowNumBackgroundColor === '') ? '미설정' : properties.rowNumBackgroundColor;
    $c.gcm.createLabel('label="rowMouseOver=true / focusMode=both / rowNumVisible=true / rowStatusVisible=true / selectedRowOverColor=red (고정) / rowNumRowMouseOverColor=' + lblNumOver + ' / rowNumBackgroundColor=' + lblNumBg + ' 로 GridView 생성. 포커스 Row 오버 시 RowNum / RowStatus / 일반 Body 셀 배경색 출력. RowNum 은 rowNumRowMouseOverColor=true 이거나 rowNumBackgroundColor 미설정 시 selectedRowOverColor 적용, RowStatus 는 항상 적용"', '', 'label1');

    // dataList 생성 (헬퍼와 동일하게 col1~col4 컬럼 구성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// 지정한 Body Cell 을 포커스시키는 사전상태 설정 (마우스 오버는 사용자 동작으로 수행)
//  - rowIndex 는 par_ 콤보에서 선택 (col 은 0 고정)
scwin.btn_setFocusedCell_onclick = function () {
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);

    // DataList currentRow 정합성 유지
    dlt_bind.setRowPosition(rowIndex);
    target1.setFocusedCell(rowIndex, 0);

    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 설정] Row(" + rowIndex + ") 포커스. 해당 Row 에 마우스를 오버하세요.");
}



// 마우스가 오버되면 자동 출력 (onbodymouseover)
//  - 포커스된 Body Row 오버 시 RowNum / RowStatus / 일반 Body 셀의 실제 적용 배경색 출력
//      · RowNum Cell   : rowNumRowMouseOverColor=true 또는 rowNumBackgroundColor 미설정 시 selectedRowOverColor 적용
//                        (단, 엔진은 미설정 시 기본값 #e5eff7 을 채워 미설정 경로는 미적용)
//      · RowStatus Cell: 항상 selectedRowOverColor 적용
//      · 일반 Body Cell: selectedRowOverColor 적용 (포커스 Row 오버 기준)
scwin.target1_onbodymouseover = function (info) {
    let fRowIndex = target1.getFocusedRowIndex();
    let overRow = info.rowIndex;

    // 포커스된 Row 가 없으면 (사전상태 미설정) 안내만 출력
    if (fRowIndex === null || fRowIndex === undefined || fRowIndex < 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[안내] 먼저 setFocusedCell 로 포커스 Row 를 설정하세요.");
        return;
    }

    // 포커스된 Row 를 오버한 경우에만 selectedRowOverColor 검증
    if (overRow !== fRowIndex) {
        wf_body_bottom.getObj("scwin").setReturnValue("[안내] 포커스된 Row(" + fRowIndex + ") 에 마우스를 오버하세요. (현재 Row " + overRow + " 오버)");
        return;
    }

    // RowNum Cell 배경색
    let numTd = document.querySelector("td[id*='target1_headerRowNumber_bodyRow_" + fRowIndex + "']");
    let numColor = numTd ? window.getComputedStyle(numTd).backgroundColor : "(cell 없음)";

    // RowStatus Cell 배경색
    let statusTd = document.querySelector("td[id*='target1_headerRowStatus_bodyRow_" + fRowIndex + "']");
    let statusColor = statusTd ? window.getComputedStyle(statusTd).backgroundColor : "(cell 없음)";

    // 일반 Body Cell 배경색 (참조용)
    let bodyTd = document.querySelector("td[id*='target1_cell_" + fRowIndex + "_0']");
    let bodyColor = bodyTd ? window.getComputedStyle(bodyTd).backgroundColor : "(cell 없음)";

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbodymouseover (포커스 Row " + fRowIndex + " 오버)=====");
    wf_body_bottom.getObj("scwin").setReturnValue("[RowNum Cell 배경색 → 조건부 selectedRowOverColor] " + numColor);
    wf_body_bottom.getObj("scwin").setReturnValue("[RowStatus Cell 배경색 → 항상 selectedRowOverColor] " + statusColor);
    wf_body_bottom.getObj("scwin").setReturnValue("[일반 Body Cell 배경색 → selectedRowOverColor] " + bodyColor);
}
